+// Copyright The OpenTelemetry Authors
+// SPDX-License-Identifier: Apache-2.0
+
+// Package semconv maps Stripe API requests onto OpenTelemetry semantic
+// conventions.
+//
+// It deliberately depends only on the standard library and OpenTelemetry, never
+// on github.com/stripe/stripe-go. The hook package converts *stripe.Error into
+// the version-neutral APIError below, so a new stripe-go major version only
+// touches the hook, not this package.
+package semconv
+
+import (
+	"context"
+	"fmt"
+	"strconv"
+	"strings"
+
+	"go.opentelemetry.io/otel/attribute"
+	"go.opentelemetry.io/otel/codes"
+	"go.opentelemetry.io/otel/metric"
+	semconv "go.opentelemetry.io/otel/semconv/v1.37.0"
+)
+
+const (
+	// DefaultServerAddress is the Stripe API host used when the request URL does
+	// not carry one.
+	DefaultServerAddress = "api.stripe.com"
+
+	// IDPlaceholder replaces resource identifiers in templated URL paths.
+	IDPlaceholder = "{id}"
+
+	// MetricRequestDuration is the latency of a logical Stripe API request,
+	// including any network retries the backend performs internally.
+	MetricRequestDuration = "stripe.client.request.duration"
+
+	// AttrRequestID carries the Stripe "Request-Id" response header, the value
+	// Stripe support and the dashboard's request log key off.
+	AttrRequestID = attribute.Key("stripe.request_id")
+	// AttrErrorCode is stripe.Error.Code (e.g. "card_declined").
+	AttrErrorCode = attribute.Key("stripe.error.code")
+	// AttrErrorType is stripe.Error.Type (e.g. "card_error").
+	AttrErrorType = attribute.Key("stripe.error.type")
+)
+
+// APIError is a version-neutral view of a Stripe API error. Zero values mean
+// "not reported by Stripe" and are omitted from telemetry.
+type APIError struct {
+	StatusCode int
+	Code       string
+	Type       string
+	RequestID  string
+}
+
+// Request describes one logical Stripe API request.
+type Request struct {
+	Method string
+	// Path is the real request path, e.g. "/v1/customers/cus_NffrFeUfNV2Hib".
+	Path string
+	// ServerAddress is optional; defaults to DefaultServerAddress when empty.
+	ServerAddress string
+	// ServerPort is the resolved port, including the scheme default. Zero means
+	// unknown and is omitted.
+	ServerPort int
+}
+
+// SpanName returns the span name for a Stripe API request: the HTTP method plus
+// the templated path, so it stays low-cardinality per OTel span-naming rules.
+func SpanName(method, path string) string {
+	method = normalizeMethod(method)
+	tmpl := TemplatePath(path)
+	if tmpl == "" {
+		return method
+	}
+	return method + " " + tmpl
+}
+
+// TemplatePath replaces resource identifiers in a Stripe API path with
+// IDPlaceholder, turning the unbounded set of real paths into the bounded set of
+// API endpoints:
+//
+//	/v1/customers/cus_NffrFeUfNV2Hib/sources/card_1Mvo → /v1/customers/{id}/sources/{id}
+//	/v1/payment_intents                                → /v1/payment_intents
+//	/v2/core/events/evt_1Mvo                           → /v2/core/events/{id}
+//
+// ponytail: shape-based, not a route table. Stripe IDs whose value is chosen by
+// the user rather than generated by Stripe (plan, coupon, product and SKU IDs
+// such as /v1/coupons/summer) do not match the opaque-ID shape and pass through
+// untemplated. Swap in a generated route table from Stripe's OpenAPI spec if
+// that cardinality ever shows up in practice; a route table is the only way to
+// close the gap, since "summer" is indistinguishable from a resource name.
+func TemplatePath(path string) string {
+	path = strings.TrimSpace(path)
+	if path == "" {
+		return ""
+	}
+	if i := strings.IndexAny(path, "?#"); i >= 0 {
+		path = path[:i]
+	}
+
+	segments := strings.Split(path, "/")
+	for i, seg := range segments {
+		// Index 0 is empty for a rooted path; index 1 is the API version, and
+		// the segment right after it always names a resource or namespace.
+		if i <= 2 || seg == "" {
+			continue
+		}
+		if isResourceID(seg) {
+			segments[i] = IDPlaceholder
+		}
+	}
