body:
`findInstrumentationYAMLFile` duplicates `findToolFile` (lines 43-64) almost verbatim — same canonical/alias existence checks, same both-exist error shape, differing only in the two path constants and one word in the error string. Given there are now two of these (and potentially more filename pairs down the line), consider factoring out the shared logic, e.g.:

```suggestion
func findOneOf(moduleDir, canonicalName, aliasName, label string) (string, error) {
	canonical := filepath.Join(moduleDir, canonicalName)
	alias := filepath.Join(moduleDir, aliasName)

	canonicalExists := util.PathExists(canonical)
	aliasExists := util.PathExists(alias)

	switch {
	case canonicalExists && aliasExists:
		return "", ex.Newf(
			"both %q and %q exist; only one %s file is allowed",
			canonicalName,
			aliasName,
			label,
		)
	case canonicalExists:
		return canonical, nil
	case aliasExists:
		return alias, nil
	default:
		return "", nil
	}
}

func findInstrumentationYAMLFile(moduleDir string) (string, error) {
	return findOneOf(moduleDir, InstrumentationYAMLCanonical, InstrumentationYAMLAlias, "instrumentation YAML")
}
```

`findToolFile` would then become a one-line wrapper around the same helper.

